//! Compares hs-dsp with the C++ captures in `compat/golden/core` (generated by `tools/compat-golden`
//! from `libs/ssdsp`). The scenarios are re-stated from `tools/compat-golden/main.cpp::dspGoldens`;
//! DSP outputs must match within 1e-6 absolute (-120 dBFS), the same bound as `--compare` in C++.
use hs_dsp::dsp::*;
use std::path::PathBuf;

pub const RATE: u32 = 48000;
pub const BLOCK: usize = 256;
const SEED: u32 = 0x1357_9BDF;
const PI: f64 = std::f64::consts::PI;

pub fn golden(name: &str) -> Vec<f32> {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../compat/golden/core")
        .join(name);
    let b = std::fs::read(&p).unwrap_or_else(|e| panic!("{p:?}: {e}"));
    b.as_chunks::<4>()
        .0
        .iter()
        .map(|c| f32::from_le_bytes(*c))
        .collect()
}

pub fn assert_close(name: &str, got: &[f32], want: &[f32], tol: f32) {
    assert_eq!(got.len(), want.len(), "{name}: length");
    let (mut worst, mut at) = (0.0f32, 0);
    for (i, (a, b)) in got.iter().zip(want).enumerate() {
        let d = (a - b).abs();
        if d > worst {
            (worst, at) = (d, i);
        }
    }
    assert!(
        worst <= tol,
        "{name}: max error {worst:e} at sample {at} (got {}, want {})",
        got[at],
        want[at]
    );
}

pub fn random_sample(state: &mut u32) -> f32 {
    *state = state.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
    (*state >> 8) as f32 / 8_388_608.0 - 1.0
}

pub fn sine(frame: u64, rate: u32, hz: f64) -> f32 {
    (2.0 * PI * hz * (frame % u64::from(rate)) as f64 / f64::from(rate)).sin() as f32
}

pub fn music(frame: u64, rate: u32) -> f32 {
    const NOTES: [f64; 4] = [220.0, 330.0, 275.0, 440.0];
    let note = ((frame / u64::from(rate / 4)) % 4) as usize;
    let envelope =
        0.65 + 0.35 * (2.0 * PI * (frame % u64::from(rate)) as f64 / f64::from(rate)).sin();
    envelope as f32 * (0.22 * sine(frame, rate, NOTES[note]) + 0.10 * sine(frame, rate, 110.0))
}

fn stereo(out: &mut Vec<f32>, l: &[f32], r: &[f32]) {
    for (a, b) in l.iter().zip(r) {
        out.push(*a);
        out.push(*b);
    }
}

#[test]
fn inputs_match() {
    let mut seed = SEED;
    let (mut tone, mut noise, mut music_lr) = (vec![], vec![], vec![]);
    for i in 0..RATE {
        tone.push(0.5 * sine(u64::from(i), RATE, 440.0));
        noise.push(random_sample(&mut seed));
        music_lr.push(music(u64::from(i), RATE));
        music_lr.push(music(u64::from(i) + 37, RATE));
    }
    assert_close("sine", &tone, &golden("inputs/sine.f32"), 1e-6);
    assert_eq!(noise, golden("inputs/noise.f32"), "noise must be exact");
    assert_close("music", &music_lr, &golden("inputs/music.f32"), 1e-6);
}

#[test]
fn smoother_matches_golden() {
    let mut s = Smoother::default();
    s.prepare(f64::from(RATE), 5.0);
    s.snap(0.0);
    s.set_target(1.0);
    let mut ramp = vec![];
    for i in 0..2048 {
        if i == 600 {
            s.set_target(0.25);
        }
        if i == 1200 {
            s.set_target(0.0);
        }
        ramp.push(s.next_value());
    }
    assert!(ramp[2047] == 0.0 && !s.is_smoothing());
    assert_close("smoother", &ramp, &golden("dsp/smoother.f32"), 1e-6);
}

#[test]
fn pan_matches_golden() {
    let mut out = vec![];
    for i in 0..2049u64 {
        let (l, r) = pan_gains(i as f32 / 1024.0 - 1.0);
        let t = 0.5 * sine(i, RATE, 440.0);
        out.extend([t * l, t * r]);
    }
    assert_close("pan", &out, &golden("dsp/pan.f32"), 1e-6);
}

#[test]
fn limiter_matches_golden() {
    let (mut seed, mut tone, mut noise) = (SEED, vec![], vec![]);
    for i in 0..RATE {
        tone.push(0.5 * sine(u64::from(i), RATE, 440.0));
        noise.push(random_sample(&mut seed));
    }
    let mut lim = Limiter::default();
    lim.prepare(f64::from(RATE), 1.0, 100.0);
    let ceiling = db_to_gain(-1.0);
    lim.set_ceiling(ceiling);
    let mut out = vec![];
    for block in 0..188usize {
        let (mut l, mut r) = (vec![0.0f32; BLOCK], vec![0.0f32; BLOCK]);
        for i in 0..BLOCK {
            let at = (block * BLOCK + i) % tone.len();
            l[i] = if block < 40 {
                tone[at]
            } else if block < 80 {
                noise[at] * 4.0
            } else {
                tone[at] * 0.25
            };
            r[i] = l[i] * -0.75;
            if block == 80 && i == 0 {
                l[0] = 3.0;
            }
        }
        let enabled = block < 160;
        lim.process(&mut l, &mut r, BLOCK, enabled);
        if enabled {
            assert!(
                block_peak(&l).max(block_peak(&r)) <= ceiling + 1e-6,
                "ceiling exceeded"
            );
        }
        stereo(&mut out, &l, &r);
    }
    assert_close("limiter", &out, &golden("dsp/limiter.f32"), 1e-6);
}

#[test]
fn loudness_matches_golden() {
    let mut m = LoudnessMeter::default();
    m.prepare(f64::from(RATE));
    let mut levels = vec![];
    let mut l = vec![0.0f32; BLOCK];
    for block in 0..750usize {
        for (i, x) in l.iter_mut().enumerate() {
            let peak = if block < 562 { 0.1 } else { 0.2 };
            *x = peak * sine((block * BLOCK + i) as u64, RATE, 1000.0);
        }
        m.process(&l, &l, BLOCK);
        levels.extend([m.momentary(), m.short_term()]);
    }
    assert!(m.momentary() > -30.0 && m.short_term() > -30.0);
    assert_close("loudness", &levels, &golden("dsp/loudness.f32"), 1e-6);
}

#[test]
fn drift_matches_golden() {
    let mut d = DriftController::default();
    d.reset(1440.0);
    let mut fill = 1440.0f64;
    let mut out = vec![];
    for i in 0..1200 {
        if i == 400 {
            fill += 128.0;
        }
        if i == 800 {
            fill -= 64.0;
        }
        if i == 600 {
            d.set_target(1600.0);
        }
        let c = d.update(fill + f64::from(i % 3) * 64.0, 0.01);
        out.extend([c as f32, d.filtered_error() as f32, d.target() as f32]);
        fill += 480.0 * (1.0 + 200.0e-6) - 480.0 * (1.0 + c);
    }
    assert_close("drift", &out, &golden("dsp/drift.f32"), 1e-6);
}

#[test]
fn resampler_matches_golden() {
    use hs_dsp::resampler::VarResampler;
    let mut rs = VarResampler::new(44100, RATE, 5).unwrap();
    let mut cursor = 0u64;
    let (mut audio, mut counts) = (vec![], vec![]);
    for block in 0..100 {
        let ppm = match block {
            0..25 => 0,
            25..50 => 150,
            50..75 => -200,
            _ => 0,
        };
        if block == 75 {
            rs.reset();
        }
        rs.set_correction_ppm(ppm);
        let mut used = rs.input_for(480);
        let mut made = 480u32;
        let il: Vec<f32> = (0..used)
            .map(|i| music(cursor + u64::from(i), 44100))
            .collect();
        let ir: Vec<f32> = (0..used)
            .map(|i| 0.5 * sine(cursor + u64::from(i), 44100, 441.0))
            .collect();
        let (mut ol, mut or) = (vec![0.0f32; 480], vec![0.0f32; 480]);
        rs.process([&il, &ir], &mut used, [&mut ol, &mut or], &mut made);
        assert_eq!(
            made, 480,
            "resampler failed to fill output at block {block}"
        );
        cursor += u64::from(used);
        stereo(&mut audio, &ol, &or);
        counts.extend([used as f32, made as f32, ppm as f32]);
    }
    assert_close(
        "resampler_counts",
        &counts,
        &golden("dsp/resampler_counts.f32"),
        1e-6,
    );
    assert_close("resampler", &audio, &golden("dsp/resampler.f32"), 1e-6);
}

#[test]
fn stream_consumer_matches_golden() {
    use hs_bus::bus::random_token;
    use hs_bus::ring::ring_write;
    use hs_bus::shm::{SharedMemory, current_pid};
    use hs_dsp::consumer::StreamConsumer;
    use std::sync::atomic::Ordering::SeqCst;

    let name = format!("golden_{}_{}", current_pid(), random_token());
    let memory = SharedMemory::open(&name).unwrap();
    let bus = memory.layout();
    bus.header.hubOwnerToken.store(1, SeqCst);
    bus.header.hubOwnerPid.store(current_pid(), SeqCst);
    // pin liveness so scheduler delays cannot affect the heartbeat gate
    bus.header.hubHeartbeatNs.store(u64::MAX, SeqCst);
    bus.header.hubBlockSize.store(BLOCK as u32, SeqCst);
    bus.streamHeader.sampleRate.store(44100, SeqCst);
    bus.streamHeader.active.store(1, SeqCst);
    let mut consumer = StreamConsumer::new();
    consumer.set_report_to_hub(false);
    consumer.configure(&name, 0, 30.0, RATE);

    let (mut produced, mut producer_time) = (0u64, 0.0f64);
    let (mut captured, mut trace) = (vec![], vec![]);
    let mut input = vec![0.0f32; BLOCK];
    let (mut ol, mut or) = (vec![0.0f32; 480], vec![0.0f32; 480]);
    for tick in 0..300 {
        let now = f64::from(tick) * 0.010;
        while producer_time <= now {
            for (i, x) in input.iter_mut().enumerate() {
                *x = 0.5 * sine(produced + i as u64, 44100, 441.0);
            }
            ring_write(
                &bus.streamAudio.0[0],
                &bus.streamHeader.writePos.0[0],
                &[&input],
                BLOCK as u32,
            );
            produced += BLOCK as u64;
            producer_time += BLOCK as f64 / (44100.0 * (1.0 + 150.0e-6));
        }
        consumer.pull([&mut ol, &mut or], 480, 0.010);
        stereo(&mut captured, &ol, &or);
        let st = consumer.status();
        assert!(
            st.connected && st.hub_alive,
            "consumer lost pinned live bus"
        );
        trace.extend([
            st.buffer_ms as f32,
            st.target_ms as f32,
            st.drift_ppm as f32,
            st.underruns as f32,
            st.resyncs as f32,
        ]);
    }
    assert!(consumer.status().streaming);
    assert_close(
        "consumer_status",
        &trace,
        &golden("dsp/consumer_status.f32"),
        1e-6,
    );
    assert_close("consumer", &captured, &golden("dsp/consumer.f32"), 1e-6);
}
